import math

def is_power_of_two(n):
    if n <= 0:
        return False
    return (n & (n - 1) == 0)

solutions = []
for x in range(6, 101):
    V = x**3 + x - 2
    if V <= 0:
        # Should not happen for x >= 6
        continue

    if is_power_of_two(V):
        # Calculate k = log2(V)
        k = V.bit_length() - 1

        # Check constraints: k must be an integer and positive.
        # Since V is a power of 2, k is an integer.
        if k >= 1:
            # Solution found: (x, n=3, k)
            solutions.append((x, 3, k))

print("Found solutions (x, 3, k) for x in [6, 100]:")
if solutions:
    for sol in solutions:
        print(sol)
else:
    print("No solutions found in the range x=6 to x=100.")
